test('canonical seeker birth re-enables motion after Setup queued removal, then fails one active Run', () => {
  const world = setup(),
    bullet = seeker(world, { x: 4, y: 5, angle: 123 });
  expect(bullet.removeAfterFrame).toBe(true);
  expect(bullet.movementEnabled).toBe(true);
  tick(world, bullet);
  tick(world, bullet);
  expect([bullet.x, bullet.y, bullet.angle]).toEqual([2.35, 7.5, 123]);
  expect(bullet.movementEnabled).toBe(false);
  expect(world.runtimeFor(world.field).effectQueue.map((effect) => effect.symbol)).toEqual([1767, 1767]);
  expect(world.drainEvents().filter((event) => event.type === 'hit')).toHaveLength(1);
  expect(world.hitSoundTimer).toBe(4);
});

test('direct virtual Setup alone leaves failed seeker movement disabled without replaying its callback', () => {
  const world = setup(), bullet = createProjectile(world.nextId(), {
    owner: world.player.uid, enemy: false, kind: 'seeker', symbol: 1827,
    x: 4, y: 5, angle: 123, speed: 3, damage: 1,
  });
  initializeAvatarSeeker(world, bullet);
  expect(bullet.movementEnabled).toBe(false);
  tick(world, bullet);
  expect([bullet.x, bullet.y]).toEqual([4, 5]);
  expect(world.runtimeFor(world.field).effectQueue.map((effect) => effect.symbol)).toEqual([1767]);
});

test('friendly seeker whose target vanishes during Run completes that move once before removal', () => {
  const world = setup();
  const old = enemy(world, 100);
  const bullet = seeker(world);
  world.field.enemies = [];
  world.actorParents.sync(world);
  tick(world, bullet);
  expect(bullet.removeAfterFrame).toBe(true);
  expect(bullet.homing?.target === old).toBe(true);
  expect([bullet.x, bullet.y]).toEqual([3, 0]);
  tick(world, bullet);
  expect([bullet.x, bullet.y]).toEqual([3, 0]);
  expect(world.runtimeFor(world.field).effectQueue.map((effect) => effect.symbol)).toEqual([1767]);
  expect(world.drainEvents().filter((event) => event.type === 'hit')).toHaveLength(1);
